BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path=public,private,auth,extensions,pg_temp;
SELECT plan(32);
SELECT ok(NOT has_function_privilege('anon','private.stock_incoming(uuid)','EXECUTE'),'Incoming stock projection rejects anonymous access');
SELECT ok(has_function_privilege('authenticated','private.stock_incoming(uuid)','EXECUTE'),'Stock reader can invoke guarded physical projection');
SELECT ok(NOT has_table_privilege('authenticated','public.order_requirement_lines','SELECT'),'Incoming quantities never grant supplier line access');
SELECT has_column('public','tenancy_organizations','quotation_currency','Quotation preference has distinct currency authority');
SELECT ok(NOT has_column_privilege('authenticated','public.tenancy_organizations','quotation_currency','UPDATE'),'Browser cannot bypass owner confirmation of preferred currency');
SELECT ok(NOT has_function_privilege('anon','private.company_settings(uuid)','EXECUTE'),'Company currency authority needs verified authentication');
SELECT has_column('public','tenancy_organizations','require_mfa','Tenant can require second factor');
SELECT has_table('public','client_contacts','Contacts have their own identity');
SELECT has_table('public','client_addresses','Work addresses differ from billing address');
SELECT has_table('public','client_notes','Authored notes are evidence');
SELECT has_table('public','client_merges','Merge has before and after evidence');
SELECT has_table('public','organization_invitations','Invitations are capabilities before membership');
SELECT has_table('public','organization_admin_events','Administration preserves evidence');
SELECT ok((SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid=ANY(ARRAY['public.client_contacts'::regclass,'public.client_addresses'::regclass,'public.client_notes'::regclass,'public.client_merges'::regclass,'public.organization_invitations'::regclass,'public.organization_admin_events'::regclass])),'Every new tenant table enforces RLS');
SELECT col_not_null('public','client_addresses','org_id','Work address requires tenant');
SELECT col_not_null('public','client_merges','org_id','Merge requires tenant');
SELECT ok(NOT has_table_privilege('anon','public.client_notes','SELECT'),'Anonymous cannot read private notes');
SELECT ok(NOT has_column_privilege('authenticated','public.clients','merged_into_id','UPDATE'),'Client alias cannot be forged');
SELECT ok(NOT has_column_privilege('authenticated','public.client_addresses','client_id','UPDATE'),'Address cannot be retargeted');
SELECT ok(NOT has_column_privilege('authenticated','public.client_contacts','origin_id','INSERT'),'Contact lineage cannot be forged');
SELECT ok(NOT has_column_privilege('authenticated','public.client_notes','created_by','INSERT'),'Note actor comes from verified database claims');
SELECT ok(NOT has_column_privilege('authenticated','public.client_notes','author_label','INSERT'),'Note author label cannot be forged');
SELECT ok(NOT has_table_privilege('authenticated','public.client_notes','UPDATE'),'Notes are immutable to browser');
SELECT ok(NOT has_table_privilege('authenticated','public.organization_admin_events','INSERT'),'Browser cannot forge administration history');
SELECT ok(NOT has_column_privilege('authenticated','public.organization_invitations','token_digest','SELECT'),'Browser cannot enumerate capability hashes');
SELECT ok(NOT has_table_privilege('authenticated','public.tenancy_memberships','INSERT'),'Invitation acceptance exclusively provisions membership');
SELECT ok(NOT has_function_privilege('anon','private.accept_company_invitation(text)','EXECUTE'),'Invitation needs verified authentication');
SELECT ok(NOT has_function_privilege('anon','private.bootstrap_memberships(uuid)','EXECUTE'),'Bootstrap is limited to authenticated identity');
SELECT ok(private.client_rut_valid('76.543.210-3') AND private.client_rut_valid('12345678-5') AND NOT private.client_rut_valid('76.543.210-1'),'Chilean check digit is validated in SQL');
SELECT ok(private.client_rut_key('76.543.210-3')=private.client_rut_key('76543210-3'),'RUT punctuation cannot create another identity');
SELECT is((SELECT count(*)::integer FROM pg_trigger WHERE tgname='lock_client_statement' AND NOT tgisinternal),4,'Direct master and child edits share merge lock order');
SELECT is((SELECT count(*)::integer FROM pg_trigger WHERE tgname IN('client_note_no_truncate','client_merge_no_truncate','organization_admin_events_no_truncate')),3,'Evidence cannot be truncated');
SELECT * FROM finish();
ROLLBACK;
